/* The game's own map artwork and the shared region names, used by every page.
 *
 * Kept in one file rather than inlined into both pages so the two cannot drift apart and
 * the payload is paid for once. Every icon is trimmed to its drawn pixels and scaled to
 * fill a common 64px box, so artwork that arrived at wildly different sizes - one source
 * was 3840px square, several were 28px - still reads as the same optical weight in a row.
 *
 * The artwork is white line art on transparency: invisible against a light background,
 * correct against the dark surfaces both pages use.
 */

/* Which artwork stands for which pin type, keyed by the game's own type name. */
const PIN_ICONS = {
  BossAndTreasure: "data:image/png;base64,",  // Guarded Treasure
  TreasureHuntMappin: "data:image/png;base64,",  // Hidden Treasure
  BanditCampfire: "data:image/png;base64,",  // Bandit Camp
  MonsterNest: "data:image/png;base64,",  // Monster Nest
  RescuingTown: "data:image/png;base64,",  // Abandoned Site
  BanditCamp: "data:image/png;base64,",  // Person in Distress
  DungeonCrawl: "data:image/png;base64,",  // Monster Den
  Contraband: "data:image/png;base64,",  // Smugglers' Cache
  SpoilsOfWar: "data:image/png;base64,",  // Spoils of War
  PlaceOfPower: "data:image/png;base64,",  // Place of Power
  Hideout: "data:image/png;base64,",  // Hanse Base
  KnightErrant: "data:image/png;base64,",  // Knight Errant
  InfestedVineyard: "data:image/png;base64,",  // Infested Vineyard
  WineContract: "data:image/png;base64,",  // Vintner's Contract
};

/* Shown for a point of interest whose type has no artwork of its own.
 *
 * Two types are still unmatched - The Prophet Lebioda's Footsteps and Signal Stake, five
 * and two pins respectively, both Blood and Wine. A pin type introduced by a future game
 * update lands here too, which is the real reason this exists: an unknown type shows a
 * marker rather than nothing at all.
 */
const PIN_ICON_FALLBACK = "data:image/png;base64,";

/* Kinds with no map pin at all: a quest is not a place, and a Gwent card is not on the
 * map. These apply to the per-completion rows only - the four headline tiles keep the
 * category artwork the overlay was designed around.
 *
 * Diagrams and formulae are deliberately absent: the game draws no icon for a schematic
 * either, and the crafting tile's flask already reads correctly for both.
 */
const ROW_ICON_OVERRIDES = {
  Quest: "data:image/png;base64,",
  GwentCard: "data:image/png;base64,",
};

/* Correct artwork with nothing to attach to yet.
 *
 * The cave mouth belongs to the Entrance pin, which is tracked but never counts toward a
 * completion run, so it is never drawn in a feed of completions. The notice board is the
 * alternative quest icon: swap it into ROW_ICON_OVERRIDES.Quest to use it in place of the
 * quest marker.
 */
const SPARE_ICONS = {
  Entrance: "data:image/png;base64,",
  NoticeBoard: "data:image/png;base64,",
};

/* Prettier names for the world files the game reports. Anything unlisted falls back to
   the file's own name, so a world nobody has seen yet still shows up rather than
   vanishing.

   Shared rather than kept in the map view because the checklist names regions too, and a
   second copy would be a second answer to the same question. */
const REGION_NAMES = {
  'novigrad.w2w': 'Velen & Novigrad',
  'skellige.w2w': 'Skellige',
  'bob.w2w': 'Toussaint',
  'kaer_morhen.w2w': 'Kaer Morhen',
  'prolog_village.w2w': 'White Orchard',
  'prolog_village_winter.w2w': 'White Orchard (winter)',
  'wyzima_castle.w2w': 'Vizima',
  'spiral.w2w': 'The Spiral',
  'island_of_mist.w2w': 'Isle of Mists',
};

function regionName(world) {
  const leaf = world.split('\\').pop();
  return REGION_NAMES[leaf] || leaf.replace(/\.w2w$/, '');
}

/* One drawing per tracked category, for rows and legends.
 *
 * This used to live inside index.html, where the map view could not reach it - a
 * ReferenceError that only showed up when someone opened /map. Now that the checklist
 * needs the same five as well, it lives here with everything else shared.
 *
 * Named CATEGORY_ICONS rather than KIND_ICONS because the overlay declares a KIND_ICONS
 * of its own, built from its own artwork; two top-level `const` of the same name on one
 * page is a SyntaxError, and the overlay would simply stop loading.
 */
const CATEGORY_ICONS = {
  Quest:           "data:image/png;base64,",
  Diagram:         "data:image/png;base64,",
  Formula:         "data:image/png;base64,",
  PointOfInterest: "data:image/png;base64,",
  GwentCard:       "data:image/png;base64,",
};
